import {createValidator} from '../validation/schema';import core from '../../spec/core/schema.json';import fields from '../../spec/core/field-document.schema.json';import kinds from '../../spec/core/kind-operation.schema.json';import ts from '../../spec/core/tablespec-record-classification.schema.json';import pg from '../../spec/core/postgresql-record-classification.schema.json';import ms from '../../spec/core/sqlserver-record-classification.schema.json';import avro from '../../spec/core/avro-record-classification.schema.json';import parquet from '../../spec/core/parquet-record-classification.schema.json';import schema from '../../spec/core/structured-classification-inspection.schema.json';
export {default as structuredClassificationInspectionSchema} from '../../spec/core/structured-classification-inspection.schema.json';
export type NativeStructuredClassification=TableSpecRecordClassification|PostgresqlRecordClassification|SqlServerRecordClassification|AvroRecordClassification|ParquetRecordClassification|AvroRecordTypeClassification|ParquetRecordTypeClassification|PostgresqlCompositeClassification|PostgresqlDdlKinds;
