const validator=createValidator();for(const s of [core,fields,kinds,ts,pg,ms,avro,parquet,AvroRecordTypeSchema,ParquetRecordTypeSchema,PostgresqlCompositeSchema,ddlSchema])validator.addSchema(s);const check=validator.compile(schema);
