export async function verifyStructuredClassificationInspection(input:StructuredClassificationInspection,backend?:PostgresqlBackend):Promise<StructuredClassificationInspection> {const report=copyJson(input) as unknown as StructuredClassificationInspection;if(!check(report))throw new UmfError('CLASSIFICATION_REPORT_STRUCTURE','Invalid common classification report');const expected=await inspectStructuredClassification(report.receipt,backend);if(canonical(copyJson(report))!==canonical(copyJson(expected)))throw new UmfError('CLASSIFICATION_REPORT_STALE','Common report differs from checked native receipt');return report;}
