 let declaration:ReturnType<typeof avroRecords>[number]|undefined;
 if(nativeType?.kind==='object'&&nativeType.members.type?.kind==='string'&&['record','error'].includes(nativeType.members.type.value))declaration=records.find(r=>r.path===field.path+'/type'&&r.dependencyId===field.dependencyId);
 else {const name=nativeType?.kind==='string'?nativeType.value:nativeType?.kind==='object'&&nativeType.members.type?.kind==='string'?nativeType.members.type.value:undefined;if(name&&!['null','boolean','int','long','float','double','bytes','string'].includes(name)&&!(nativeType?.kind==='object'&&['array','map','enum','fixed','record','error'].includes(name))){const ns=field.record.includes('.')?field.record.slice(0,field.record.lastIndexOf('.')):'',qualified=name.includes('.')?name:ns?ns+'.'+name:name;declaration=records.find(r=>r.fullname===qualified);}}
