  const record=classifyAvroRecord(source,{recordModule:request.recordModule,recordId:request.recordId,mode:request.mode,nativeSource:request.nativeSource,dependencies:request.dependencies??[],path:declaration.path,...(declaration.dependencyId!==undefined?{dependencyId:declaration.dependencyId}:{}),authors:authors.filter(a=>members.some(f=>f.element.id===a.identity.element))});
